import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { minifyContractRouter } from '@orpc/contract';
import { contract } from '../../shared/api/contract';
import { migrationsModule } from './migrations';
import { openApiDocument } from './openapi';
import { swiftModule } from './swift';

/**
 * Writes every generated file: the bundled migrations, the OpenAPI document, the web client's contract, and the
 * Swift API types. A file is rewritten only when its content changes, so watchers do not loop. `--check` writes
 * nothing and fails when a file is stale, which CI runs.
 */

const root = join(import.meta.dir, '../..');
const check = process.argv.includes('--check');

const GENERATED = '// Generated by scripts/generate. Do not edit.\n';
const json = (value: unknown) => `${JSON.stringify(value, null, '\t')}\n`;
const openApi = json(await openApiDocument());

const outputs: [path: string, content: () => string][] = [
	['server/src/db/generated/migrations.ts', () => GENERATED + migrationsModule(join(root, 'server/drizzle'))],
	['shared/api/generated/openapi.json', () => openApi],
	['app-web/src/lib/generated/contract.json', () => json(minifyContractRouter(contract))],
	// The Swift generator reads the document as written, not the generator's richer types.
	['app-ios/Sources/Core/Generated/API.swift', () => swiftModule(JSON.parse(openApi))],
];

const read = (path: string) => {
	try {
		return readFileSync(path, 'utf8');
	} catch {
		return null;
	}
};

const stale: string[] = [];
for (const [path, content] of outputs) {
	const file = join(root, path);
	const next = content();
	if (read(file) === next) continue;
	stale.push(relative(root, file));
	if (check) continue;
	mkdirSync(dirname(file), { recursive: true });
	writeFileSync(file, next);
}

if (check && stale.length) {
	console.error(`Generated files are stale. Run \`bun run generate\` and commit:\n${stale.join('\n')}`);
	process.exit(1);
}
if (!check && stale.length) console.log(`generate: wrote ${stale.join(', ')}`);
